'use client'

import * as React from 'react'
import VisuallyHidden from '@radui/ui/VisuallyHidden'

import './copy-button.css'

export type CopyButtonProps = Omit<React.ComponentPropsWithoutRef<'button'>, 'children'> & {
    /** Text to copy. */
    value: string
    /** Accessible name, e.g. "Copy install command". */
    label?: string
    /** Milliseconds before returning to the copy icon. */
    resetAfter?: number
}

// The copy icon morphs into a check, and a status message says "Copied" so the
// result is announced, not just shown.
const CopyButton = ({ value, label = 'Copy', resetAfter = 1800, className, onClick, ...props }: CopyButtonProps) => {
    const [copied, setCopied] = React.useState(false)
    const timer = React.useRef<number | undefined>(undefined)
    React.useEffect(() => () => window.clearTimeout(timer.current), [])

    const handleClick = async (event: React.MouseEvent<HTMLButtonElement>) => {
        onClick?.(event)
        try {
            await navigator.clipboard.writeText(value)
            setCopied(true)
            window.clearTimeout(timer.current)
            timer.current = window.setTimeout(() => setCopied(false), resetAfter)
        } catch {
            setCopied(false)
        }
    }

    return <>
        <button type="button" aria-label={label} className={['rad-fx-copy', className].filter(Boolean).join(' ')} data-state={copied ? 'copied' : 'idle'} onClick={handleClick} {...props}>
            <svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">
                <g className="rad-fx-copy-icon">
                    <rect x="8" y="8" width="12" height="12" rx="2.5" />
                    <path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2" />
                </g>
                <path className="rad-fx-copy-check" d="M5 12.5 L10 17.5 L19 7" pathLength={1} />
            </svg>
        </button>
        <VisuallyHidden asChild><span role="status">{copied ? 'Copied' : ''}</span></VisuallyHidden>
    </>
}

export default CopyButton

.rad-fx-copy {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    padding: 0;
    border: 1px solid rgba(127, 127, 127, 0.45);
    border-radius: 10px;
    background: transparent;
    color: inherit;
    cursor: pointer;
}

.rad-fx-copy:focus-visible { outline: 2px solid currentColor; outline-offset: 2px; }

.rad-fx-copy svg {
    width: 20px;
    height: 20px;
    fill: none;
    stroke: currentColor;
    stroke-width: 1.8;
    stroke-linecap: round;
    stroke-linejoin: round;
}

.rad-fx-copy-icon {
    transform-origin: 50% 50%;
    transition: opacity 200ms ease, transform 250ms ease;
}

.rad-fx-copy-check {
    stroke: var(--rad-fx-copy-success, #4ade80);
    stroke-width: 2.4;
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
    transition: stroke-dashoffset 300ms cubic-bezier(0.6, 0.1, 0.3, 1) 120ms;
}

.rad-fx-copy[data-state='copied'] .rad-fx-copy-icon { opacity: 0; transform: scale(0.6) rotate(-12deg); }
.rad-fx-copy[data-state='copied'] .rad-fx-copy-check { stroke-dashoffset: 0; }

@media (prefers-reduced-motion: reduce) {
    .rad-fx-copy-icon, .rad-fx-copy-check { transition: none; }
}

[data-rad-fx-motion='reduce'] .rad-fx-copy-icon,
[data-rad-fx-motion='reduce'] .rad-fx-copy-check { transition: none; }
